tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/3c-relay-access-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
$PY -c "import storygame,sys; sys.exit(0 if storygame.__file__.startswith('$PWD') else 1)" || { echo "FAIL: storygame not from worktree"; exit 1; }
bad=$(git status --porcelain | awk '{print $2}' | grep -v -x -e notes.md -e pytest.out -e data/stories/continuity-initiative/world.yaml -e data/stories/continuity-initiative/plot.md -e data/stories/continuity-initiative/storylet-routes.yaml -e data/stories/continuity-initiative/handoffs.yaml -e data/stories/continuity-initiative/knowledge.yaml -e tests/test_3c_adopted_package.py -e tests/test_canonical_event_delivery.py -e tests/fixtures/continuity_initiative_pre_3c_adoption/world.yaml -e tests/fixtures/continuity_initiative_pre_3c_adoption/plot.md -e tests/fixtures/continuity_initiative_pre_3c_adoption/storylet-routes.yaml -e tests/fixtures/continuity_initiative_pre_3c_adoption/handoffs.yaml -e tests/fixtures/continuity_initiative_pre_3c_adoption/knowledge.yaml)
test -z "$bad" || { echo "FAIL: files outside ownership: $bad"; exit 1; }
git diff --quiet -- storygame || { echo "FAIL: storygame edited"; exit 1; }
$PY - <<'PYEOF' || exit 1
import yaml,sys
r=yaml.safe_load(open('data/stories/continuity-initiative/storylet-routes.yaml'))
ev=[e for e in r['canonical_resolution_events'] if e['id']=='resolution_escape'][0]
want="The captives have emerged into Los Angeles. News drones, civilians, and local responders begin arriving. Brandon’s voice comes through the emergency speakers. “Reports from other detention sites are reaching the broadcast chamber. Families of the missing are calling there for news.” Then his voice falls silent. Your barrier holds the way from the maintenance network to Rebecca's executive office open for now. The broadcast chamber remains reachable while the barrier holds."
if ev.get('delivery_text')!=want: print('FAIL delivery_text:',repr(ev.get('delivery_text'))); sys.exit(1)
h=yaml.safe_load(open('data/stories/continuity-initiative/handoffs.yaml'))
d=[x for x in h['deliveries'] if x['fact_id']=='kristin_was_bait'][0]
if d['cue_text']!='The medical terminal shows files you have not examined.': print('FAIL cue_text:',repr(d['cue_text'])); sys.exit(1)
PYEOF
for f in storylet-routes.yaml handoffs.yaml world.yaml; do cmp data/stories/continuity-initiative/$f tests/fixtures/continuity_initiative_pre_3c_adoption/$f || exit 1; done
$PY -m pytest -q --no-cov -p no:cacheprovider tests/test_canonical_event_delivery.py tests/test_3c_escape_result.py tests/test_3c_adopted_package.py tests/test_markdown_story_package.py tests/test_package_audit.py tests/test_must_convey.py tests/test_narration_safety.py tests/test_leak_terms.py tests/test_cue_text_safety.py tests/test_3c_cue_chain.py tests/test_staged_cues.py > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
$PY -m ruff format --check tests/test_3c_adopted_package.py tests/test_canonical_event_delivery.py || exit 1
git add -A -- data tests && git diff --cached -- data tests > /home/bcorfman/dev/ringer-work/3c-relay-access.patch && test -s /home/bcorfman/dev/ringer-work/3c-relay-access.patch && echo "patch exported"
